 {v:'VER',what:'the status effects sit down the left side, his notes of 2026-10-07: with nothing running no status ring is drawn there; a Stim with 6 of its 10 seconds left draws a STIM icon on the left with its ring 60 percent lit and 6s beside it; a Bandage put on at 50 draws a HEALING icon on the left, clear of the pillager board and the controls, its ring lit for the share of the heal still to come and its seconds beside it, and from 80 the same counts to the Bandage stop at 85; the green heal ring over his head is gone, and the dial that keeps it for the older check still brings it back',
run:function(){
  if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__frame)) return 'SKIP: this fixture cannot deploy';
  if(typeof tickPrepSlot!=='function'||typeof tickHeal!=='function'||typeof healReach!=='function'||typeof healCeil!=='function'||!ITEMS.bandage||typeof STIM_SEC!=='number') return 'SKIP: no heal over time or Stim in this build';
  if(typeof ctx==='undefined'||typeof wc==='undefined'||!ctx||!wc||ctx===wc) return 'SKIP: the HUD and the world do not draw on two canvases here';
  if(!(W>400&&H>300)) return 'SKIP: the pane has no layout';
  var bad=[], g=null, p=null, keep=null, keepBuzz, hadBuzz=false, buzzTaken=false, hooked=false, i, k, left, tot, sec, A, T, LB, RB, yMax=H;
